using System;using System.Collections;using System.Collections.Generic;using Ashfall.Modules.WeaponHandling;using UnityEngine;
namespace Ashfall.Integration.Playable.HandsWeapons
{
    // Actual downloaded body / independently hinged barrels plus retained source
    // functional chambers/shell pair. Host alone owns root pose and inventory.
    public sealed class R24Dt11View:MonoBehaviour
    {
        sealed class Casing{public Transform Root;public Vector3 Velocity;public float Life;}
        R23Visuals visuals;bool initialized;long openSeen=-1;readonly List<Casing> cases=new List<Casing>();int cursor;Quaternion neutralRotation=Quaternion.identity;
        public void SetNeutralRotation(Quaternion rotation){neutralRotation=rotation;}
        public bool Ready{get;private set;}public string Failure{get;private set;}public Transform Model{get;private set;}public Transform Hinge{get;private set;}public Transform Offer{get;private set;}public Transform HeldPair{get;private set;}public Transform Arrow{get;private set;}public Transform Muzzle{get;private set;}
        public void InitializeModel(Transform model){if(initialized||model==null)throw new InvalidOperationException("DT11 model initialization");initialized=true;Model=model;Hinge=Node("Source DT11 hinged barrels",Model);Hinge.localPosition=V(R24Dt11Definition.Hinge);Offer=Node("Source DT11 offered pair",Model);HeldPair=Node("Source DT11 held pair",Model);Arrow=Node("Source UP close",Model);Muzzle=Node("Source DT11 actual muzzle",Model);Muzzle.localPosition=V(R24Dt11Definition.Muzzle);visuals=new R23Visuals();StartCoroutine(LoadSafely());}
        static Transform Node(string name,Transform parent){var t=new GameObject(name).transform;t.gameObject.layer=18;t.SetParent(parent,false);return t;}
        IEnumerator Load(){yield return visuals.Load("dt11",Model);yield return visuals.Load("dt11-barrels",Hinge);yield return visuals.Load("dt11-chambers",Hinge);yield return visuals.Load("dt11-pair",Offer);yield return visuals.Load("dt11-pair",HeldPair);yield return visuals.Load("dt11-arrow",Arrow);for(int i=0;i<8;i++){var root=Node("Source DT11 ejected shell "+i,Model);yield return visuals.Load("dt11-ejected",root);root.gameObject.SetActive(false);cases.Add(new Casing{Root=root});}foreach(var group in new[]{Offer,HeldPair})foreach(var renderer in group.GetComponentsInChildren<MeshRenderer>(true))if(renderer.name.Contains(".Cap")){renderer.sharedMaterial.SetColor("_EmissionColor",new Color(.1f,.8f,.8f));renderer.sharedMaterial.EnableKeyword("_EMISSION");}foreach(var renderer in Arrow.GetComponentsInChildren<MeshRenderer>(true)){renderer.sharedMaterial.SetColor("_EmissionColor",new Color(1,.72f,.16f));renderer.sharedMaterial.EnableKeyword("_EMISSION");}visuals.ReleaseLoadedBytes();Offer.gameObject.SetActive(false);HeldPair.gameObject.SetActive(false);Arrow.gameObject.SetActive(false);Ready=true;}
        IEnumerator LoadSafely(){var stack=new Stack<IEnumerator>();stack.Push(Load());while(stack.Count>0){bool more=false;object value=null;try{more=stack.Peek().MoveNext();if(more)value=stack.Peek().Current;}catch(Exception ex){Failure=ex.Message;yield break;}if(!more){stack.Pop();continue;}var child=value as IEnumerator;if(child!=null)stack.Push(child);else yield return value;}}
        static Vector3 V(Ashfall.Core.Float3 p){return new Vector3(p.X,p.Y,p.Z);}
        void ShowPrefix(string prefix,bool visible){foreach(var renderer in Hinge.GetComponentsInChildren<MeshRenderer>(true))if(renderer.name.StartsWith(prefix,StringComparison.Ordinal))renderer.enabled=visible;}
        void PairCount(Transform pair,int reserve){foreach(var renderer in pair.GetComponentsInChildren<MeshRenderer>(true))renderer.enabled=reserve<0||reserve>=2||renderer.name.StartsWith("Shell0.",StringComparison.Ordinal);}
        public void Present(R24Dt11Owner owner,Transform support,bool usable,float seconds,bool effects=true){if(!Ready||owner==null)return;var s=owner.Snapshot;Hinge.localRotation=Quaternion.AngleAxis(s.BoltTravel*Mathf.Rad2Deg,Vector3.right);for(int i=0;i<2;i++){ShowPrefix("LiveShellCap"+i,(owner.LiveMask&(1<<i))!=0);ShowPrefix("SpentShellCap"+i,(owner.SpentMask&(1<<i))!=0);}
            bool loading=usable&&s.Phase==ReloadPhase.NeedsMagazine&&owner.Reserve!=0,held=loading&&owner.ReloadGripInProgress&&support!=null;Offer.gameObject.SetActive(loading&&!held);HeldPair.gameObject.SetActive(held);Offer.localPosition=V(R24Dt11Definition.Offer(s.BoltTravel));Offer.localRotation=Hinge.localRotation*Quaternion.Euler(90,0,0);PairCount(Offer,owner.Reserve);PairCount(HeldPair,owner.Reserve);if(held){HeldPair.SetPositionAndRotation(support.position,Hinge.rotation*Quaternion.Euler(90,0,0));HeldPair.localScale=Vector3.one;}Arrow.gameObject.SetActive(usable&&s.Phase==ReloadPhase.NeedsRack);Arrow.localPosition=V(R24Dt11Definition.CloseGrip(s.BoltTravel));
            if(openSeen>=0&&owner.OpenEvents>openSeen&&effects)EjectCasings(owner.EjectionAngle);openSeen=owner.OpenEvents;float dt=Mathf.Clamp(seconds,0,.05f);if(usable&&effects)foreach(var casing in cases)if(casing.Life>0){casing.Life-=dt;casing.Root.gameObject.SetActive(casing.Life>0);casing.Velocity+=Vector3.down*9.8f*dt;var start=casing.Root.position;var delta=casing.Velocity*dt;RaycastHit hit;if(delta.sqrMagnitude>0&&Physics.Raycast(start,delta.normalized,out hit,delta.magnitude,(1<<0)|(1<<19),QueryTriggerInteraction.Ignore)){casing.Root.position=hit.point+hit.normal*.02f;casing.Velocity=Vector3.Reflect(casing.Velocity,hit.normal)*.25f;}else casing.Root.position+=delta;}}
        void EjectCasings(float oldHingeAngle){if(cases.Count==0)return;for(int i=0;i<2;i++){var c=cases[cursor++%cases.Count];c.Root.SetParent(null,true);c.Root.SetPositionAndRotation(Model.TransformPoint(V(R24Dt11Definition.Chamber(oldHingeAngle))+Vector3.right*(i==0?-.027f:.027f)*R24Dt11Definition.ChamberFit),neutralRotation);c.Root.localScale=Vector3.one;c.Root.gameObject.SetActive(true);c.Velocity=neutralRotation*new Vector3(i==0?-.3f:.3f,1.3f,-.9f);c.Life=2;}}
        public bool IsTransient(Transform child){if(Offer!=null&&(child==Offer||child.IsChildOf(Offer))||HeldPair!=null&&(child==HeldPair||child.IsChildOf(HeldPair))||Arrow!=null&&(child==Arrow||child.IsChildOf(Arrow)))return true;foreach(var c in cases)if(c.Root!=null&&(child==c.Root||child.IsChildOf(c.Root)))return true;return false;}
        // Pure geometry query for Root reachable-drop checks. Never rewrites model/tracked transforms.
        public bool TryGetBounds(R24Dt11Owner owner,out Bounds bounds){bounds=new Bounds();if(!Ready||owner==null)return false;bool any=false;var desired=Matrix4x4.TRS(Hinge.localPosition,Quaternion.AngleAxis(owner.Snapshot.BoltTravel*Mathf.Rad2Deg,Vector3.right),Vector3.one);foreach(var filter in Model.GetComponentsInChildren<MeshFilter>(true)){if(filter.sharedMesh==null||filter.name.StartsWith("R23 feedback",StringComparison.Ordinal)||IsTransient(filter.transform))continue;bool live=false,spent=false;for(int i=0;i<2;i++){if(filter.name.StartsWith("LiveShellCap"+i,StringComparison.Ordinal)){live=true;if((owner.LiveMask&(1<<i))==0)spent=true;}if(filter.name.StartsWith("SpentShellCap"+i,StringComparison.Ordinal)){live=true;if((owner.SpentMask&(1<<i))==0)spent=true;}}if(live&&spent)continue;var matrix=filter.transform.IsChildOf(Hinge)?desired*Hinge.worldToLocalMatrix*filter.transform.localToWorldMatrix:Model.worldToLocalMatrix*filter.transform.localToWorldMatrix;matrix=Matrix4x4.Scale(Vector3.one*R24Dt11Definition.Scale)*matrix;var b=filter.sharedMesh.bounds;for(int i=0;i<8;i++){var point=matrix.MultiplyPoint3x4(b.center+Vector3.Scale(b.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1)));if(!any){bounds=new Bounds(point,Vector3.zero);any=true;}else bounds.Encapsulate(point);}}return any;}
        // Static source lobby dock is a fresh authored model, independent of
        // the discarded live097 preview. This changes art only, never ammo.
        public void PresentDock(){ClearTransient();if(Hinge==null)return;Hinge.localRotation=Quaternion.identity;for(int i=0;i<2;i++){ShowPrefix("LiveShellCap"+i,true);ShowPrefix("SpentShellCap"+i,false);}openSeen=-1;}
        public void SynchronizeInstance(R24Dt11Owner owner){openSeen=owner==null?-1:owner.OpenEvents;}
        public void ClearTransient(){if(Offer!=null)Offer.gameObject.SetActive(false);if(HeldPair!=null)HeldPair.gameObject.SetActive(false);if(Arrow!=null)Arrow.gameObject.SetActive(false);foreach(var c in cases){c.Life=0;if(c.Root!=null)c.Root.gameObject.SetActive(false);}}
        void OnDestroy(){ClearTransient();foreach(var c in cases)if(c.Root!=null)Destroy(c.Root.gameObject);if(visuals!=null)visuals.Dispose();}
    }
}
